/** @jest-environment node */

const fs = require('fs');
const path = require('path');
const os = require('os');
const {
  processTranslations,
  saveFullResponse,
  saveTranslationsAsJson,
} = require('../processTranslations');

jest.mock('fs');

describe('processTranslations', () => {
  it('extracts language entries from api response', () => {
    expect(
      processTranslations({
        data: {
          'en-US': { main: { entries: {} } },
        },
      })
    ).toEqual({
      'en-US': { main: { entries: {} } },
    });
  });

  it('logs invalid response structure', () => {
    const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    const logSpy = jest.spyOn(console, 'log').mockImplementation(() => {});

    expect(processTranslations({ invalid: true })).toEqual({});

    errorSpy.mockRestore();
    logSpy.mockRestore();
  });

  it('ignores non-object language entries', () => {
    expect(
      processTranslations({
        data: {
          'en-US': 'invalid',
        },
      })
    ).toEqual({});
  });
});

describe('saveFullResponse', () => {
  beforeEach(() => {
    fs.existsSync.mockReturnValue(false);
    fs.mkdirSync.mockImplementation(() => {});
    fs.writeFileSync.mockImplementation(() => {});
    jest.spyOn(console, 'log').mockImplementation(() => {});
  });

  afterEach(() => {
    console.log.mockRestore();
    jest.clearAllMocks();
  });

  it('creates output directory and writes data.json', () => {
    saveFullResponse({ data: {} }, '/tmp/output');

    expect(fs.mkdirSync).toHaveBeenCalledWith('/tmp/output', { recursive: true });
    expect(fs.writeFileSync).toHaveBeenCalledWith(
      path.join('/tmp/output', 'data.json'),
      expect.any(String),
      'utf8'
    );
  });

  it('skips mkdir when directory already exists', () => {
    fs.existsSync.mockReturnValue(true);

    saveFullResponse({ data: {} }, '/tmp/output');

    expect(fs.mkdirSync).not.toHaveBeenCalled();
  });
});

describe('saveTranslationsAsJson', () => {
  const outputDir = path.join(os.tmpdir(), 'tms-test-output');

  beforeEach(() => {
    fs.writeFileSync.mockImplementation(() => {});
    jest.spyOn(console, 'log').mockImplementation(() => {});
    jest.spyOn(console, 'warn').mockImplementation(() => {});
  });

  afterEach(() => {
    console.log.mockRestore();
    console.warn.mockRestore();
    jest.clearAllMocks();
  });

  it('writes nested locale file', () => {
    const filePath = saveTranslationsAsJson(
      'en-US',
      {
        main: {
          entries: {
            'homePage.title': { v: 'Home' },
          },
        },
      },
      outputDir,
      false
    );

    expect(filePath).toBe(path.join(outputDir, 'en-US.json'));
    expect(fs.writeFileSync).toHaveBeenCalled();
  });

  it('writes MFE and shared keys without shared-components namespace wrapper', () => {
    saveTranslationsAsJson(
      'en-US',
      {
        main: {
          entries: {
            'hub-analytics.homePage.title': { v: 'Analytics Home' },
            'shared-components.SurveyModal.JourneyModal.title': { v: 'How was your experience?' },
          },
        },
      },
      outputDir,
      false
    );

    const writtenContent = JSON.parse(fs.writeFileSync.mock.calls[0][1]);
    expect(writtenContent).toEqual({
      'hub-analytics': {
        homePage: {
          title: 'Analytics Home',
        },
        SurveyModal: {
          JourneyModal: {
            title: 'How was your experience?',
          },
        },
      },
    });
  });

  it('returns null when no entries are found', () => {
    const filePath = saveTranslationsAsJson('en-US', {}, outputDir, false);
    expect(filePath).toBeNull();
  });
});
